<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\ReturnRequest;use App\Models\SupportTicket;use Illuminate\Http\Request;
class ReturnSupportController extends Controller{public function returns(){return view('admin.operations.returns',['returns'=>ReturnRequest::with(['user','orderItem.order','orderItem.product'])->latest()->paginate(20)]);}public function resolveReturn(Request $r,ReturnRequest $return){$d=$r->validate(['status'=>['required','in:approved,rejected,refunded'],'resolution'=>['required','string','max:2000'],'refund_amount'=>['nullable','integer','min:0']]);$return->update($d+['resolved_by'=>$r->user()->id,'resolved_at'=>now()]);return back()->with('status','Решение сохранено.');}public function tickets(){return view('admin.operations.tickets',['tickets'=>SupportTicket::with(['user','order'])->withCount('messages')->latest()->paginate(20)]);} }
